```javascript
import { useEffect, useState } from "react";

/**
 * Returns `value` only after it has stopped changing for `delayMs` milliseconds.
 *
 * @template T
 * @param {T} value - The value to debounce.
 * @param {number} delayMs - How long the value must remain unchanged, in milliseconds.
 * @returns {T} The debounced value.
 */
export function useDebouncedValue(value, delayMs) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    // Schedule an update. Any previous timer for an older value is cleared
    // by the cleanup function of the previous effect run.
    const timerId = setTimeout(() => {
      setDebouncedValue(value);
    }, delayMs);

    // Cleanup: runs before the next effect and on unmount.
    // Cancelling the timer ensures stale values are never committed
    // and no state update happens after unmount.
    return () => {
      clearTimeout(timerId);
    };
  }, [value, delayMs]);

  return debouncedValue;
}
```

**Usage example:**

```javascript
import { useState } from "react";
import { useDebouncedValue } from "./useDebouncedValue";

function SearchBox() {
  const [query, setQuery] = useState("");
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    if (debouncedQuery) {
      // e.g. fetch results only once typing has paused for 300ms
      console.log("Searching for:", debouncedQuery);
    }
  }, [debouncedQuery]);

  return (
    <input
      value={query}
      onChange={(e) => setQuery(e.target.value)}
      placeholder="Search..."
    />
  );
}
```

**How it works:**

- On every change of `value` or `delayMs`, the effect schedules a `setTimeout`.
- If `value` changes again before the timer fires, the cleanup clears the previous timer, so only the latest value survives.
- When the timer fires, the debounced state updates to the latest value.
- On unmount, the cleanup clears any pending timer, so no state update runs on an unmounted component.
- The hook returns the initial `value` on first render, so there is no delay on mount.
